  'published',
  'started',
  'start-failed',
  'cue-failed',
  'preflight-failed',
  'poll-failed',
] as const;
const RECOVERY_PREPARATION_RESULTS = ['ready', 'failed'] as const;

const CONNECTION_STATES = [
